const slotsInUse = `-- name: SlotsInUse :many
SELECT slot FROM slots WHERE repo = ? ORDER BY slot
`

func (q *Queries) SlotsInUse(ctx context.Context, repo string) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, slotsInUse, repo)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var slot int64
		if err := rows.Scan(&slot); err != nil {
			return nil, err
		}
		items = append(items, slot)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

